query Event($id: ID!) {
  event(id: $id) {
  id
  name
  startDate
  endDate
  timezone
  isMultiDay
  status
  customTimeInstruction
  attendanceMode
  isFoodIncluded
  foodDetails
  descriptionText
  descriptionHtml
  shareUrl
  type { value }
  tags { name }
  hostGroup { id name }
  cohostGroups { id name }
  parent { id name }
  location {
    kind
    name
    isToBeDetermined
    eventLocationPrivacy
    address { street city state zipcode }
    coordinates { latitude longitude }
  }
  onlineMeeting { platform meetingLinkPrivacy }
  externalRegistration { url }
  registration {
    capacityMode
    registrationUrl
    options { name price { amount currency isFlexible } }
  }
}
}

